mapper.select:
SELECT db2.hid, MAX(h.baseName) as hospital_name, COUNT(db2.rid) as regist_doctors, IFNULL(MAX(db.db_doctor),0) as null_doctor, ROUND(IFNULL(MAX(db.db_doctor),0)/COUNT(db2.rid),2)*100 as null_percentage FROM doctor_basic db2 LEFT JOIN ( SELECT db.hid,count(*) as db_doctor FROM doctor_career dc INNER JOIN doctor_basic db ON dc.rid = db.rid WHERE 1=1 and JSON_SEARCH(CONVERT(dc.jsondata,JSON), 'all', '경력', null, '$[*].type') IS NULL
AND db.hid = #{hid}
GROUP BY db.hid ) db on db2.hid = db.hid LEFT JOIN hospital h ON db2.hid = h.hid WHERE 1=1
AND db2.hid = #{hid}
GROUP BY db2.hid ORDER BY db2.hid

SELECT db.doctorname, h.baseName, db.doctor_url, dc.jsondata FROM doctor_career dc INNER JOIN doctor_basic db ON dc.rid = db.rid INNER JOIN hospital h ON db.hid = h.hid WHERE 1=1 and JSON_SEARCH(CONVERT(dc.jsondata,JSON), 'one', '경력', null, '$[*].type') IS NULL
AND db.hid = #{hid}
ORDER BY db.hid

SELECT db2.hid, MAX(h.baseName) as hospital_name, COUNT(db2.rid) as regist_doctors, IFNULL(MAX(db.db_doctor),0) as null_doctor, ROUND(IFNULL(MAX(db.db_doctor),0)/COUNT(db2.rid),2)*100 as null_percentage FROM doctor_basic db2 LEFT JOIN ( SELECT db.hid,count(*) as db_doctor FROM doctor_career dc INNER JOIN doctor_basic db ON dc.rid = db.rid WHERE 1=1 and JSON_SEARCH(CONVERT(dc.jsondata,JSON), 'all', '학력', null, '$[*].type') IS NULL
AND db.hid = #{hid}
GROUP BY db.hid ) db on db2.hid = db.hid LEFT JOIN hospital h ON db2.hid = h.hid WHERE 1=1
AND db2.hid = #{hid}
GROUP BY db2.hid ORDER BY db2.hid

SELECT db.doctorname, h.baseName, db.doctor_url, dc.jsondata FROM doctor_career dc INNER JOIN doctor_basic db ON dc.rid = db.rid INNER JOIN hospital h ON db.hid = h.hid WHERE 1=1 and JSON_SEARCH(CONVERT(dc.jsondata,JSON), 'one', '학력', null, '$[*].type') IS NULL
AND db.hid = #{hid}
ORDER BY db.hid

SELECT tot.hid, MAX(h.baseName) as hospital_name, COUNT(tot.rid) as regist_doctors, SUM(CASE WHEN tot.paper_cnt = 0 THEN 1 ELSE 0 END) as null_doctor, ROUND(SUM(CASE WHEN tot.paper_cnt = 0 THEN 1 ELSE 0 END) / COUNT(tot.rid),1)*100 as null_percentage FROM ( SELECT db2.hid, db2.rid, IFNULL(max(db.paper_cnt),0) as paper_cnt FROM doctor_basic db2 LEFT JOIN ( SELECT db.hid,db.rid,ifnull(count(dp.title),0) as paper_cnt FROM doctor_basic db LEFT JOIN doctor_paper dp ON db.rid = dp.rid WHERE 1=1
AND db.hid = #{hid}
GROUP BY db.hid,db.rid ) db on db2.hid = db.hid and db2.rid = db.rid WHERE 1=1
AND db.hid = #{hid}
GROUP BY db2.hid,db2.rid ) as tot LEFT JOIN hospital h ON tot.hid = h.hid WHERE 1=1 GROUP BY tot.hid ORDER BY tot.hid asc

SELECT tot.hid, MAX(h.baseName) as hospital_name, COUNT(tot.rid) as all_doctor_count, SUM(CASE WHEN tot.all_paper_cnt > 0 THEN 1 ELSE 0 END) as paper_reg_doctor_count, ROUND(SUM(CASE WHEN tot.all_paper_cnt > 0 THEN 1 ELSE 0 END) / COUNT(tot.rid),2)*100 as reg_per_all_percentage, SUM(CASE WHEN tot.pubmed_paper_cnt > 0 THEN 1 ELSE 0 END) as pubmed_reg_doctor_count, ROUND(SUM(CASE WHEN tot.pubmed_paper_cnt > 0 THEN 1 ELSE 0 END) / COUNT(tot.rid),2)*100 as pubmed_per_all_percentage FROM ( SELECT db2.hid, db2.rid, IFNULL(MAX(dp_all.paper_cnt),0) as all_paper_cnt, IFNULL(MAX(dp_pubmed.paper_cnt),0) as pubmed_paper_cnt FROM doctor_basic db2 left join ( SELECT rid,count(*) as paper_cnt FROM doctor_paper WHERE 1=1 GROUP BY rid ) dp_all ON db2.rid = dp_all.rid LEFT JOIN ( SELECT rid,ifnull(count(pmid),0) as paper_cnt FROM doctor_paper WHERE 1=1 and pmid IS NOT NULL GROUP BY rid ) dp_pubmed on db2.rid = dp_pubmed.rid GROUP BY db2.hid,db2.rid ) as tot LEFT JOIN hospital h ON tot.hid = h.hid WHERE 1=1
AND tot.hid = #{hid}
GROUP BY tot.hid ORDER BY tot.hid asc

SELECT tot.hid, MAX(h.baseName) as hospital_name, COUNT(tot.rid) as all_doctor_count, SUM(CASE WHEN tot.all_paper_cnt > 0 THEN 1 ELSE 0 END) as paper_reg_doctor_count, ROUND(SUM(CASE WHEN tot.all_paper_cnt > 0 THEN 1 ELSE 0 END) / COUNT(tot.rid),2)*100 as reg_per_all_percentage, SUM(CASE WHEN tot.pubmed_paper_cnt > 0 THEN 1 ELSE 0 END) as pubmed_reg_doctor_count, ROUND(SUM(CASE WHEN tot.pubmed_paper_cnt > 0 THEN 1 ELSE 0 END) / COUNT(tot.rid),2)*100 as pubmed_per_all_percentage FROM ( SELECT db2.hid, db2.rid, IFNULL(MAX(dp_all.paper_cnt),0) as all_paper_cnt, IFNULL(MAX(dp_pubmed.paper_cnt),0) as pubmed_paper_cnt FROM doctor_basic db2 left join ( SELECT rid,count(*) as paper_cnt FROM doctor_paper WHERE 1=1 GROUP BY rid ) dp_all ON db2.rid = dp_all.rid LEFT JOIN ( SELECT rid,ifnull(count(pmid),0) as paper_cnt FROM doctor_paper WHERE 1=1 and pmid IS NOT NULL GROUP BY rid ) dp_pubmed on db2.rid = dp_pubmed.rid GROUP BY db2.hid,db2.rid ) as tot LEFT JOIN hospital h ON tot.hid = h.hid WHERE 1=1
AND tot.hid = #{hid}
GROUP BY tot.hid ORDER BY tot.hid asc

SELECT db2.hid, IFNULL(dp_all.paper_cnt,0) as all_paper_cnt, IFNULL(dp_pubmed.paper_cnt,0) as pubmed_paper_cnt, ROUND(IFNULL(dp_pubmed.paper_cnt,0) / IFNULL(dp_all.paper_cnt,0),1)*100 as pubmed_per_all_percentage FROM doctor_basic db2 LEFT JOIN ( SELECT db.hid,count(*) as paper_cnt FROM doctor_basic db INNER JOIN doctor_paper as dp ON db.rid = dp.rid WHERE 1=1
AND db.hid = #{hid}
GROUP BY db.hid ) dp_all ON db2.hid = dp_all.hid LEFT JOIN ( SELECT db.hid,count(*) as paper_cnt FROM doctor_basic db INNER JOIN doctor_paper as dp ON db.rid = dp.rid WHERE 1=1
AND db.hid = #{hid}
and dp.pmid IS NOT NULL GROUP BY db.hid ) dp_pubmed ON db2.hid = dp_pubmed.hid WHERE 1=1
AND db2.hid = #{hid}
GROUP BY db2.hid

SELECT tot.hid, MAX(h.baseName) as hospital_name, COUNT(tot.rid) as all_doctor_count, SUM(CASE WHEN tot.all_paper_cnt > 0 THEN 1 ELSE 0 END) as paper_reg_doctor_count, ROUND(SUM(CASE WHEN tot.all_paper_cnt > 0 THEN 1 ELSE 0 END) / COUNT(tot.rid),2)*100 as reg_per_all_percentage, SUM(CASE WHEN tot.pubmed_paper_cnt > 0 THEN 1 ELSE 0 END) as pubmed_reg_doctor_count, ROUND(SUM(CASE WHEN tot.pubmed_paper_cnt > 0 THEN 1 ELSE 0 END) / COUNT(tot.rid),2)*100 as pubmed_per_all_percentage FROM ( SELECT db2.hid, db2.rid, IFNULL(MAX(dp_all.paper_cnt),0) as all_paper_cnt, IFNULL(MAX(dp_pubmed.paper_cnt),0) as pubmed_paper_cnt FROM doctor_basic db2 left join ( SELECT rid,count(*) as paper_cnt FROM doctor_paper WHERE 1=1 GROUP BY rid ) dp_all ON db2.rid = dp_all.rid LEFT JOIN ( SELECT rid,ifnull(count(journalName),0) as paper_cnt FROM doctor_paper WHERE 1=1 and journalName IS NOT NULL GROUP BY rid ) dp_pubmed on db2.rid = dp_pubmed.rid GROUP BY db2.hid,db2.rid ) as tot LEFT JOIN hospital h ON tot.hid = h.hid WHERE 1=1
AND tot.hid = #{hid}
GROUP BY tot.hid ORDER BY tot.hid asc

SELECT tot.hid, MAX(h.baseName) as hospital_name, COUNT(tot.rid) as all_doctor_count, SUM(CASE WHEN tot.all_paper_cnt > 0 THEN 1 ELSE 0 END) as paper_reg_doctor_count, ROUND(SUM(CASE WHEN tot.all_paper_cnt > 0 THEN 1 ELSE 0 END) / COUNT(tot.rid),2)*100 as reg_per_all_percentage, SUM(CASE WHEN tot.pubmed_paper_cnt > 0 THEN 1 ELSE 0 END) as pubmed_reg_doctor_count, ROUND(SUM(CASE WHEN tot.pubmed_paper_cnt > 0 THEN 1 ELSE 0 END) / COUNT(tot.rid),2)*100 as pubmed_per_all_percentage FROM ( SELECT db2.hid, db2.rid, IFNULL(MAX(dp_all.paper_cnt),0) as all_paper_cnt, IFNULL(MAX(dp_pubmed.paper_cnt),0) as pubmed_paper_cnt FROM doctor_basic db2 left join ( SELECT rid,count(*) as paper_cnt FROM doctor_paper WHERE 1=1 GROUP BY rid ) dp_all ON db2.rid = dp_all.rid LEFT JOIN ( SELECT rid,ifnull(count(title_pubmed),0) as paper_cnt FROM doctor_paper WHERE 1=1 and title_pubmed IS NOT NULL GROUP BY rid ) dp_pubmed on db2.rid = dp_pubmed.rid GROUP BY db2.hid,db2.rid ) as tot LEFT JOIN hospital h ON tot.hid = h.hid WHERE 1=1
AND tot.hid = #{hid}
GROUP BY tot.hid ORDER BY tot.hid asc

SELECT tot.hid, MAX(h.baseName) as hospital_name, COUNT(tot.rid) as all_doctor_count, SUM(CASE WHEN tot.all_paper_cnt > 0 THEN 1 ELSE 0 END) as paper_reg_doctor_count, ROUND(SUM(CASE WHEN tot.all_paper_cnt > 0 THEN 1 ELSE 0 END) / COUNT(tot.rid),2)*100 as reg_per_all_percentage, SUM(CASE WHEN tot.pubmed_paper_cnt > 0 THEN 1 ELSE 0 END) as pubmed_reg_doctor_count, ROUND(SUM(CASE WHEN tot.pubmed_paper_cnt > 0 THEN 1 ELSE 0 END) / COUNT(tot.rid),2)*100 as pubmed_per_all_percentage FROM ( SELECT db2.hid, db2.rid, IFNULL(MAX(dp_all.paper_cnt),0) as all_paper_cnt, IFNULL(MAX(dp_pubmed.paper_cnt),0) as pubmed_paper_cnt FROM doctor_basic db2 left join ( SELECT rid,count(*) as paper_cnt FROM doctor_paper WHERE 1=1 GROUP BY rid ) dp_all ON db2.rid = dp_all.rid LEFT JOIN ( SELECT rid,ifnull(count(doi),0) as paper_cnt FROM doctor_paper WHERE 1=1 and doi IS NOT NULL GROUP BY rid ) dp_pubmed on db2.rid = dp_pubmed.rid GROUP BY db2.hid,db2.rid ) as tot LEFT JOIN hospital h ON tot.hid = h.hid WHERE 1=1
AND tot.hid = #{hid}
GROUP BY tot.hid ORDER BY tot.hid asc
